head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setFooterCaption]<br/>GridView 컴포넌트의 Footer Table 에 caption 요소를 설정합니다.",
    "validation" : [
        "GridView 컴포넌트의 Footer Table 에 caption 요소를 설정합니다.",
        "label(필수) 파라미터로 Footer Table 의 caption 요소에 적용될 텍스트를 설정합니다.",
        "caption 요소가 이미 존재하면 텍스트를 교체하고, 존재하지 않으면 새로 생성하여 Footer Table 의 colgroup 앞에 삽입합니다.",
        "setFooterCaption() 메소드는 렌더링 된 caption 값만 변경하며 footerCaption 값은 변경하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // dataList 생성
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // 조건 읽기
    //  - con_footerCaption : 문자열. 빈 값이면 footerCaption 속성을 부여하지 않음(미설정) → Footer caption 요소 없음
    //                        값 설정 시 footerCaption 속성 부여 → 초기 caption 요소 존재
    let footerCaptionVal = con_footerCaption.getValue();

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // Property 설정은 createCList 공통 함수 사용 (빈 문자열 value 는 자동 제외 → 미설정 처리)
    let cList = $c.gcm.createCList({ footerCaption: footerCaptionVal, dataList: "data:dlt_bind", checkAllType: "false" });

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblFooterCaption = (footerCaptionVal === '') ? '미설정(Footer caption 요소 없음)' : footerCaptionVal + ' (Footer caption 요소 존재)';
    $c.gcm.createLabel('label="footerCaption=' + lblFooterCaption + ' 로 GridView 생성 (Header 4컬럼 + gBody + Footer 1행)"', '', 'label1');

    // target 생성 (footerCaption 조건부, Footer Table 포함)
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setFooterCaption 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="사번"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="이름"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="부서"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="직급"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft1" value="합계"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Footer Table 의 caption 요소 텍스트를 DOM 으로 읽어 반환 (없으면 null)
scwin.getFooterCaptionText = function () {
    let footTable = document.querySelector("table[id*='target1_foot_table']");
    if (!footTable) {
        return null;
    }
    let caption = footTable.getElementsByTagName("caption")[0];
    return caption ? caption.textContent : null;
}



// Footer Table 의 caption 요소가 colgroup 앞에 위치하는지 확인 (@spec1)
//  - caption 요소가 colgroup 의 바로 이전 형제(previousElementSibling)인지로 판단
scwin.isFooterCaptionBeforeColgroup = function () {
    let footTable = document.querySelector("table[id*='target1_foot_table']");
    if (!footTable) {
        return null;
    }
    let caption = footTable.getElementsByTagName("caption")[0];
    let colgroup = footTable.getElementsByTagName("colgroup")[0];
    if (!caption || !colgroup) {
        return false;
    }
    return colgroup.previousElementSibling === caption;
}



// 현재 Footer Table caption 요소 텍스트 / 위치 확인 (@spec1 / @spec2 사전 상태 확인)
scwin.btn_checkFooterCaption_onclick = function () {
    let captionText = scwin.getFooterCaptionText();
    wf_body_bottom.getObj("scwin").setReturnValue("렌더 caption 요소 : " + (captionText === null ? '미생성(caption 요소 없음)' : "'" + captionText + "'"));
    wf_body_bottom.getObj("scwin").setReturnValue("footerCaption 속성값 : '" + target1.options.footerCaption + "'");
}



// setFooterCaption 호출 후 렌더 caption / footerCaption 옵션값 / colgroup 앞 위치 출력
scwin.btn_setFooterCaption_onclick = function () {
    let label = par_label.getValue();
    target1.setFooterCaption(label);

    wf_body_bottom.getObj("scwin").setReturnValue("setFooterCaption('" + label + "') 호출");
    // @spec1 : 이미 존재하면 교체 / 없으면 새로 생성하여 colgroup 앞에 삽입
    wf_body_bottom.getObj("scwin").setReturnValue("[렌더 caption(변경됨)] " + scwin.getFooterCaptionText());
    wf_body_bottom.getObj("scwin").setReturnValue("[caption 이 colgroup 앞에 위치] " + scwin.isFooterCaptionBeforeColgroup());
    // @spec2 : 렌더 caption 값만 변경, footerCaption 속성값은 미변경
    wf_body_bottom.getObj("scwin").setReturnValue("[footerCaption 속성값(미변경)] '" + target1.options.footerCaption + "'");
}
